/// <summary>
/// Assigns an item identity profile to a Warehouse Management mobile app menu item. The
/// injection service only adds the identity display line to menu items with an enabled
/// setting record.
/// </summary>
public class AAXWHSItemIdentityMenuItemSetting extends common
{
}

Method.Source:
/// <summary>
/// Finds the setting record for the specified mobile app menu item.
/// </summary>
/// <param name = "_name">The menu item name.</param>
/// <param name = "_forUpdate">True to select the record for update.</param>
/// <returns>The setting record, or an empty buffer when none exists.</returns>
public static AAXWHSItemIdentityMenuItemSetting findByMenuItem(WHSMenuItemName _name, boolean _forUpdate = false)
{
    AAXWHSItemIdentityMenuItemSetting menuItemSetting;

    if (_name)
    {
        menuItemSetting.selectForUpdate(_forUpdate);

        select firstonly menuItemSetting
            where menuItemSetting.MenuItemName == _name;
    }

    return menuItemSetting;
}

/// <summary>
/// Derives the partner context of a mobile app menu item from its work execution mode.
/// Purchase order receiving modes yield a vendor context, work execution modes yield a
/// customer context, and everything else yields no partner context.
/// </summary>
/// <param name = "_name">The menu item name.</param>
/// <returns>The partner context of the menu item.</returns>
public static AAXWHSItemIdentityPartnerContext partnerContextForMenuItem(WHSMenuItemName _name)
{
    WHSRFMenuItemTable menuItemTable = WHSRFMenuItemTable::find(_name);

    if (!menuItemTable)
    {
        return AAXWHSItemIdentityPartnerContext::None;
    }

    switch (WHSRFMenuItemTable::getWHSWorkExecuteMode(menuItemTable))
    {
        case WHSWorkExecuteMode::PurchaseOrderLineReceiving:
        case WHSWorkExecuteMode::PurchaseOrderLineReceivingAndLocate:
        case WHSWorkExecuteMode::PurchaseOrderItemReceiving:
        case WHSWorkExecuteMode::PurchaseOrderItemReceivingAndLocate:
            return AAXWHSItemIdentityPartnerContext::Vendor;

        case WHSWorkExecuteMode::UserDirected:
        case WHSWorkExecuteMode::SystemDirected:
        case WHSWorkExecuteMode::UserGrouping:
        case WHSWorkExecuteMode::SystemGrouping:
        case WHSWorkExecuteMode::PickPack:
            return AAXWHSItemIdentityPartnerContext::Customer;
    }

    return AAXWHSItemIdentityPartnerContext::None;
}

/// <summary>
/// Shows the derived partner context of the assigned menu item as a read-only column.
/// </summary>
/// <returns>The partner context of the menu item.</returns>
public display AAXWHSItemIdentityPartnerContext partnerContext()
{
    return AAXWHSItemIdentityMenuItemSetting::partnerContextForMenuItem(this.MenuItemName);
}

/// <summary>
/// Initializes a new setting record as enabled.
/// </summary>
public void initValue()
{
    super();

    this.Enabled = NoYes::Yes;
}

/// <summary>
/// Validates the setting and warns when the profile has only partner-dependent sources but
/// the menu item derives no partner context.
/// </summary>
/// <returns>True if the record is valid; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    if (ret && AAXWHSItemIdentityMenuItemSetting::partnerContextForMenuItem(this.MenuItemName) == AAXWHSItemIdentityPartnerContext::None)
    {
        AAXWHSItemIdentityProfileLine anyLine;
        AAXWHSItemIdentityProfileLine nonExternalLine;

        select firstonly RecId from anyLine
            where anyLine.ProfileId == this.ProfileId;

        select firstonly RecId from nonExternalLine
            where nonExternalLine.ProfileId == this.ProfileId
               && nonExternalLine.Source != AAXWHSItemIdentitySource::ExternalItemNumber;

        // Warn only
        if (anyLine.RecId != 0 && nonExternalLine.RecId == 0)
        {
            warning(strFmt("@AAXWarehouseTools:IdentitySetupWarnPartner", this.MenuItemName));
        }
    }

    return ret;
}
